"""Exploratory test: is a cut path, when one exists, always found inside a minimum cut generated by few vertices?

For a pair (u, v) and one maximum flow with residual digraph R:
  H1   some cut delta(A_x), A_x = R-closure of {u, x} (x any vertex, v not in A_x), contains a u-v path;
  H1'  some cut delta(V - B_y), B_y = set of vertices that reach v or y in R (u not in B_y), contains one;
  H2   some cut delta(A_xy), A_xy = R-closure of {u, x, y}, contains one.
Each of these is a polynomial test (n, n, n^2 minimum cuts).  Tested on every pair with d(u,v) = 2, c(u,v) >= 3
that has a cut path: all connected graphs with <= 8 vertices, random instances of search.py (all four generators,
9..16 vertices), the family F(k), k <= 5.
Usage: python test_generated_cuts.py <seconds per worker> <workers>
"""

import os
import random
import sys
import time
from multiprocessing import Pool

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import cutpaths as cpz  # noqa: E402
from cutpaths import mcp, Gr, PairInfo  # noqa: E402
import search  # noqa: E402
import family  # noqa: E402

CACHE = os.path.normpath(os.path.join(HERE, "..", "..", "..", "..", "tmp", "clanok-2-checks"))


def cut_has_path(g, A, u, v):
    C = cpz.cut_mask_of_side(g, A)
    return mcp.connected(g, u, v, removed=g.full() ^ C)


def tests(g, u, v, P):
    n = g.n
    reach = P.reach
    co = [0] * n                      # co[y] = vertices that reach y
    for x in range(n):
        r = reach[x]
        for y in range(n):
            if (r >> y) & 1:
                co[y] |= 1 << x
    full = (1 << n) - 1
    h1 = h1b = h2 = False
    for x in range(n):
        A = reach[u] | reach[x]
        if not (A >> v) & 1 and cut_has_path(g, A, u, v):
            h1 = True
            break
    for y in range(n):
        B = co[v] | co[y]
        if not (B >> u) & 1 and cut_has_path(g, full ^ B, u, v):
            h1b = True
            break
    if h1 or h1b:
        h2 = True
    else:
        for x in range(n):
            for y in range(x + 1, n):
                A = reach[u] | reach[x] | reach[y]
                if not (A >> v) & 1 and cut_has_path(g, A, u, v):
                    h2 = True
                    break
            if h2:
                break
    return h1, h1b, h2


def analyze(g):
    out = []
    D = mcp.dist_matrix(g)
    isdc = cpz.in_dc(g, D)
    for u in range(g.n):
        for v in range(u + 1, g.n):
            if D[u][v] != 2:
                continue
            P = PairInfo(g, u, v)
            if P.c < 3:
                continue
            if not P.cut_paths(first=True):
                continue
            Ls, _ = P.shortest_cut_path()
            out.append((isdc, Ls, tests(g, u, v, P), u, v))
    return out


def tally(tal, ex, key, g, res):
    for isdc, Ls, (h1, h1b, h2), u, v in res:
        k = "%s|%s|L%d" % (key, "DC" if isdc else "notDC", Ls)
        t = tal.setdefault(k, [0, 0, 0, 0, 0])
        t[0] += 1
        t[1] += h1
        t[2] += h1b
        t[3] += h1 or h1b
        t[4] += h2
        if not (h1 or h1b) and len(ex) < 20:
            ex.append((isdc, g.n, g.m, cpz.fmt(g), u, v, Ls, h2))


def small_worker(item):
    n, es = item
    g = Gr(n, es)
    tal, ex = {}, []
    tally(tal, ex, "n<=8", g, analyze(g))
    return tal, ex


def rand_worker(args):
    seed, seconds = args
    rng = random.Random(seed)
    t0 = time.time()
    tal, ex = {}, []
    while time.time() - t0 < seconds:
        gname = rng.choice(["gnp", "ears", "planted", "family", "family"])
        n = rng.randint(9, 16)
        g = search.GENS[gname](rng, n)
        if g is None:
            continue
        tally(tal, ex, "random", g, analyze(g))
    return tal, ex


def merge(tot, exs, tal, ex):
    for k, t in tal.items():
        tt = tot.setdefault(k, [0] * 5)
        for i in range(5):
            tt[i] += t[i]
    exs += ex


def main():
    seconds = float(sys.argv[1]) if len(sys.argv) > 1 else 60
    workers = int(sys.argv[2]) if len(sys.argv) > 2 else 32
    t0 = time.time()
    tot, exs = {}, []
    items = []
    for n in range(2, 9):
        items += mcp.connected_graphs(n, CACHE)
    with Pool(workers) as pool:
        for tal, ex in pool.imap_unordered(small_worker, items, chunksize=16):
            merge(tot, exs, tal, ex)
        for tal, ex in pool.imap_unordered(rand_worker, [(5000 + i, seconds) for i in range(workers)]):
            merge(tot, exs, tal, ex)
    for k in range(1, 6):
        g, u, v = family.family(k, True)
        P = PairInfo(g, u, v)
        Ls, _ = P.shortest_cut_path()
        tally(tot, exs, "family F(k)", g, [(cpz.in_dc(g), Ls, tests(g, u, v, P), u, v)])
    lines = ["test_generated_cuts.py: pairs with d = 2, c >= 3 and a cut path; %d workers x %.0f s random" % (workers, seconds),
             "", "columns: pairs | H1 (closure of {u,x}) | H1' (complement of co-closure of {v,y}) | H1 or H1' | H2 (closure of {u,x,y})"]
    for k in sorted(tot):
        lines.append("%-28s %8d %8d %8d %8d %8d" % (k, *tot[k]))
    lines.append("")
    lines.append("Pairs where neither H1 nor H1' finds a path (DC first): (DC, n, m, edges, u, v, shortest, H2)")
    exs.sort(key=lambda e: (not e[0], e[1], e[2]))
    for e in exs[:10]:
        lines.append("  %r" % (e,))
    lines.append("Time %.0f s." % (time.time() - t0))
    with open(os.path.join(HERE, "results-generated-cuts.txt"), "w") as f:
        f.write("\n".join(lines) + "\n")
    print("\n".join(lines))


if __name__ == "__main__":
    main()
